//! FFI bindings into Go/gnark's multisig-policy circuit library.

use alloy_primitives::B256;
use ark_bn254::Fr;
use k256::ecdsa::{Signature, VerifyingKey};
use tint::{
    circuit::join_split::{N_INPUTS, N_OUTPUTS, N_WITHDRAWALS},
    fr::address_to_fr,
    note::{commitment::Commitment, withdrawal::Withdrawal},
    operation::OperationWitness,
};

use crate::{N_SIGNERS, ffi::artifacts::Artifacts};

pub mod artifacts;
mod bytes32;
mod operation_hash_test;
mod poseidon2_test;
mod pubkey_hash_test;

/// Generated by build.rs from go via bindgen. See `go/ffi/tint.h` for
/// documentation of the C types and functions.
#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all,
    clippy::pedantic
)]
mod bindings {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}
use bindings::{
    Bytes32, FreeBytes, TintBaseCommitment, TintHardwareWalletProve, TintHardwareWalletProveInput,
    TintOperation, TintProve, TintProveInput, TintPubKeyXY, TintSignatureRS,
    TintSpendableCommitment, TintWithdrawal,
};

#[derive(Clone, Debug, thiserror::Error)]
pub enum FfiError {
    #[error("Prove failed with status code {0}")]
    ProveFailed(u8),
    #[error(transparent)]
    InvalidPublicKey(#[from] crate::pubkey_hash::InvalidPublicKey),
}

/// Generates a proof for the multisig-policy circuit using gnark
/// for the given inputs.
///
/// Returns the proof as solidity-verifier-compatible bytes on success or
/// the status code on failure.
pub fn prove_via_go(
    artifacts: &Artifacts,
    policy_address: Fr,
    operation: &OperationWitness<N_INPUTS, N_OUTPUTS, N_WITHDRAWALS>,
    context_hash: Fr,
    pub_keys: &[VerifyingKey; N_SIGNERS],
    signatures: &[Option<Signature>; N_SIGNERS],
) -> Result<Vec<u8>, FfiError> {
    let mut input = TintProveInput {
        policy_address: policy_address.into(),
        operation: operation.into(),
        context_hash: context_hash.into(),
        pub_keys: tint::array::try_from_fn(|i| TintPubKeyXY::try_from(&pub_keys[i]))?,
        signatures: std::array::from_fn(|i| signatures[i].as_ref().into()),
    };

    call_prove(artifacts, |ccs, pk, vk, proof_ptr, proof_len| unsafe {
        TintProve(
            ccs.0,
            ccs.1,
            pk.0,
            pk.1,
            vk.0,
            vk.1,
            &raw mut input,
            proof_ptr,
            proof_len,
        )
    })
}

/// Generates a proof for the hardware-wallet-policy circuit using gnark,
/// for `signature` by `pub_key` over the EIP-712 `digest`.
///
/// Returns the proof as solidity-verifier-compatible bytes on success or
/// the status code on failure.
pub fn prove_hardware_wallet_via_go(
    artifacts: &Artifacts,
    policy_address: Fr,
    operation: &OperationWitness<N_INPUTS, N_OUTPUTS, N_WITHDRAWALS>,
    context_hash: Fr,
    digest: B256,
    pub_key: &VerifyingKey,
    signature: &Signature,
) -> Result<Vec<u8>, FfiError> {
    let mut input = TintHardwareWalletProveInput {
        policy_address: policy_address.into(),
        operation: operation.into(),
        context_hash: context_hash.into(),
        digest: Bytes32 { data: digest.0 },
        pub_key: TintPubKeyXY::try_from(pub_key)?,
        signature: Some(signature).into(),
    };

    call_prove(artifacts, |ccs, pk, vk, proof_ptr, proof_len| unsafe {
        TintHardwareWalletProve(
            ccs.0,
            ccs.1,
            pk.0,
            pk.1,
            vk.0,
            vk.1,
            &raw mut input,
            proof_ptr,
            proof_len,
        )
    })
}

type RawBuf = (*mut u8, usize);

/// Calls a Go prove function with `artifacts`, taking ownership of its proof.
fn call_prove(
    artifacts: &Artifacts,
    prove: impl FnOnce(RawBuf, RawBuf, RawBuf, *mut *mut u8, *mut usize) -> u8,
) -> Result<Vec<u8>, FfiError> {
    let raw = |buf: &Vec<u8>| (buf.as_ptr().cast_mut(), buf.len());
    let mut proof_ptr: *mut u8 = std::ptr::null_mut();
    let mut proof_len: usize = 0;

    let status = prove(
        raw(&artifacts.ccs),
        raw(&artifacts.pk),
        raw(&artifacts.vk),
        &raw mut proof_ptr,
        &raw mut proof_len,
    );

    if status != 0 {
        return Err(FfiError::ProveFailed(status));
    }

    let proof = unsafe { std::slice::from_raw_parts(proof_ptr, proof_len) }.to_vec();
    unsafe { FreeBytes(proof_ptr) };
    Ok(proof)
}

impl From<&OperationWitness<N_INPUTS, N_OUTPUTS, N_WITHDRAWALS>> for TintOperation {
    fn from(op: &OperationWitness<N_INPUTS, N_OUTPUTS, N_WITHDRAWALS>) -> Self {
        let inputs = std::array::from_fn(|i| {
            let input = &op.inputs[i].note;
            TintSpendableCommitment {
                inner: (&input.note).into(),
                policy_address: address_to_fr(input.policy.address).into(),
                policy_witness: input.policy.witness.into(),
            }
        });
        let output_commitments = std::array::from_fn(|i| (&op.outputs[i]).into());
        let output_withdrawals = std::array::from_fn(|i| (&op.withdrawals[i]).into());

        TintOperation {
            inputs,
            output_commitments,
            output_withdrawals,
        }
    }
}

impl From<&Commitment> for TintBaseCommitment {
    fn from(c: &Commitment) -> Self {
        TintBaseCommitment {
            asset_fr: c.asset_fr().into(),
            amount_fr: c.amount_fr().into(),
            policy_hash: c.policy_hash.into(),
            random_fr: c.random_fr().into(),
            nullifier_pub_key: c.nullifier_pub_key.0.into(),
        }
    }
}

impl From<&Withdrawal> for TintWithdrawal {
    fn from(w: &Withdrawal) -> Self {
        TintWithdrawal {
            asset_fr: w.asset_fr().into(),
            amount_fr: w.amount_fr().into(),
            recipient_fr: w.recipient_fr().into(),
        }
    }
}

impl TryFrom<&VerifyingKey> for TintPubKeyXY {
    type Error = crate::pubkey_hash::InvalidPublicKey;

    fn try_from(vk: &VerifyingKey) -> Result<Self, Self::Error> {
        let (x, y) = crate::pubkey_hash::encoded_xy(vk)?;
        Ok(TintPubKeyXY {
            x: Bytes32 { data: x },
            y: Bytes32 { data: y },
        })
    }
}

/// A missing signature is encoded as `r = s = 0`, which the circuit's
/// ECDSA-verify gadget treats as automatically invalid.
impl From<Option<&Signature>> for TintSignatureRS {
    fn from(sig: Option<&Signature>) -> Self {
        let Some(sig) = sig else {
            return TintSignatureRS {
                r: Bytes32 { data: [0u8; 32] },
                s: Bytes32 { data: [0u8; 32] },
            };
        };
        let (r, s) = sig.split_bytes();
        TintSignatureRS {
            r: Bytes32 { data: r.into() },
            s: Bytes32 { data: s.into() },
        }
    }
}

